module logic;
use model {Sample,Summary,Outcome};
use util {reverse};
record RunState {pending:List<Sample>,answer:Outcome<Summary>}

fn convert(sample:Sample)->Outcome<I64> {
 if sample.raw < 0 {Err(11)} else {
  if sample.scale <= 0 {Err(12)} else {Ok(sample.raw*sample.scale)}
 }
}

fn run(samples:List<Sample>)->Outcome<Summary> {
 let final=while(state:RunState=RunState {
  pending:samples,
  answer:Ok(Summary {values:List::empty<I64>(),total:0,maximum:0})
 }; List::length(state.pending) != 0 && match (state.answer) {
  Ok(summary)=>true,
  Err(code)=>false
 }) {
  match (state.answer) {
   Err(code)=>RunState {pending:List::tail(state.pending),answer:Err(code)},
   Ok(summary)=>match (convert(List::head(state.pending))) {
    Err(code)=>RunState {pending:List::tail(state.pending),answer:Err(code)},
    Ok(amount)=>RunState {
     pending:List::tail(state.pending),
     answer:Ok(Summary {
      values:List::prepend(amount,summary.values),
      total:summary.total+amount,
      maximum:if amount > summary.maximum {amount} else {summary.maximum}
     })
    }
   }
  }
 }; match (final.answer) {
  Ok(summary)=>Ok(Summary {
   values:reverse(summary.values),
   total:summary.total,
   maximum:summary.maximum
  }),
  Err(code)=>Err(code)
 }
}

